vec4 blur(sampler2D texture, vec2 uvOrigin) {
  vec4 col = vec4(0.0);
  for(float index = 0.0; index < 10.0; index++){
    vec2 uv = uvOrigin + vec2((index/9.0 - 0.5) * (blurAmount/100.0), 0.0);
    col += texture2D(texture, uv);
  }
  col = col / 10.0;
  return col;
}
